import { Injectable, signal } from '@angular/core';
import { APP_CONFIG } from '../config';
import { AyahRef } from '../models';

/**
 * Shape of `content/<edition>/translation-id.json`, generated by
 * scripts/build-content.mjs (never hand-edited, never machine-translated).
 * Keys are "surah:ayah".
 */
export interface TranslationFile {
  format: 'mushaf-translation';
  version: 1;
  lang: 'id';
  source: {
    name: string;
    edition: string;
    url: string;
    origin: string;
    license: string;
    fetchedAt: string;
  };
  ayahs: Record<string, string>;
}

/**
 * Indonesian translation (Kemenag RI, edisi 2019) per ayah. Loaded lazily on
 * first use and kept in memory; the service worker caches the file afterwards.
 */
@Injectable({ providedIn: 'root' })
export class TranslationService {
  private file: Promise<TranslationFile | null> | null = null;
  readonly source = signal<TranslationFile['source'] | null>(null);

  /** Resolves to the translation, or null when unavailable (offline before first load, missing file). */
  async get(ref: AyahRef): Promise<string | null> {
    const f = await this.load();
    return f?.ayahs[`${ref.surah}:${ref.ayah}`] ?? null;
  }

  /** Whole file, for features that need every ayah (e.g. translation search). */
  all(): Promise<TranslationFile | null> {
    return this.load();
  }

  private load(): Promise<TranslationFile | null> {
    this.file ??= fetch(`${APP_CONFIG.contentBase}/${APP_CONFIG.editionId}/translation-id.json`)
      .then(async (r) => {
        if (!r.ok) throw new Error(String(r.status));
        const f = (await r.json()) as TranslationFile;
        if (f.format !== 'mushaf-translation' || typeof f.ayahs !== 'object') throw new Error('format');
        this.source.set(f.source);
        return f;
      })
      .catch(() => {
        this.file = null; // retry on the next request (e.g. after coming back online)
        return null;
      });
    return this.file;
  }
}
